use serde_json::{json, Value};
use std::{fs, path::{Path, PathBuf}, process::Command};
fn supported(path:&Path)->bool{matches!(path.extension().and_then(|v|v.to_str()),Some("rs"|"js"|"ts"|"tsx"|"jsx"|"py"|"go"|"java"|"c"|"cpp"|"h"|"hpp"))}
fn binary(root:&Path)->Option<PathBuf>{if let Some(path)=std::env::var_os("LUME_ASTRA_BIN"){return Some(PathBuf::from(path));}let mut candidates=vec![root.join("third-party/ast-grep/target/release/ast-grep.exe"),root.join("third-party/ast-grep/target/release/ast-grep")];if let Ok(exe)=std::env::current_exe(){if let Some(parent)=exe.parent(){candidates.push(parent.join("ast-grep.exe"));candidates.push(parent.join("ast-grep"));}for parent in exe.ancestors().skip(1).take(4){candidates.push(parent.join("third-party/ast-grep/target/release/ast-grep.exe"));candidates.push(parent.join("third-party/ast-grep/target/release/ast-grep"));}}candidates.into_iter().find(|path|path.is_file())}
pub fn search(root:&Path,args:&Value)->Result<Value,String>{let pattern=args["pattern"].as_str().filter(|v|!v.is_empty()).ok_or("ASTRA needs a structural pattern.")?;let lang=args["language"].as_str().unwrap_or("javascript");if let Some(bin)=binary(root){if let Ok(out)=Command::new(bin).args(["run","--pattern",pattern,"--lang",lang,root.to_string_lossy().as_ref()]).output(){if out.status.success(){return Ok(json!({"tool":"ASTRA","operation":"search","pattern":pattern,"language":lang,"structural":true,"matches":String::from_utf8_lossy(&out.stdout).to_string()}));}}}
let mut hits=Vec::new();for entry in walkdir::WalkDir::new(root).follow_links(false).into_iter().filter_map(Result::ok){let path=entry.path();if !entry.file_type().is_file()||!supported(path){continue;}let Ok(text)=fs::read_to_string(path)else{continue;};for(line_no,line)in text.lines().enumerate(){if line.contains(pattern){hits.push(json!({"path":path.strip_prefix(root).unwrap_or(path).to_string_lossy().replace('\\',"/"),"line":line_no+1,"preview":line.trim()}));}}}Ok(json!({"tool":"ASTRA","operation":"search","pattern":pattern,"language":lang,"structural":false,"notice":"Native ast-grep unavailable; text fallback used.","matches":hits}))}
pub fn preview_replace(root:&Path,args:&Value)->Result<Value,String>{let path=args["path"].as_str().ok_or("ASTRA replacement needs a path.")?;let old=args["old_text"].as_str().ok_or("ASTRA replacement needs old_text.")?;let new=args["new_text"].as_str().ok_or("ASTRA replacement needs new_text.")?;let full=super::path(root,path)?;let text=fs::read_to_string(&full).map_err(|e|e.to_string())?;let count=text.matches(old).count();if count==0{return Err("ASTRA found no matching structure.".into());}Ok(json!({"tool":"ASTRA","operation":"preview_replace","path":path,"matches":count,"replacement":new,"changed":false}))}
